/// Localized standard résumé section headers + a market-conventional date
/// range example.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ResumeConventions {
    pub summary: &'static str,
    pub experience: &'static str,
    pub education: &'static str,
    pub skills: &'static str,
    pub date_example: &'static str,
}

/// Résumé conventions for `lang`, falling back to English for any locale the
/// prompt side has no curated entry for — the same normalization
/// (first two characters, lowercased) and the same fallback as the TS
/// `resumeConventions`.
pub fn resume_conventions(lang: &str) -> ResumeConventions {
    let key: String = lang.chars().take(2).flat_map(char::to_lowercase).collect();
    match key.as_str() {
        "de" => ResumeConventions {
            summary: "Profil",
            experience: "Berufserfahrung",
            education: "Ausbildung",
            skills: "Kenntnisse",
            date_example: "01/2021 – 03/2023",
        },
        "es" => ResumeConventions {
            summary: "Perfil",
            experience: "Experiencia profesional",
            education: "Formación",
            skills: "Habilidades",
            date_example: "enero 2021 – marzo 2023",
        },
        "fr" => ResumeConventions {
            summary: "Profil",
            experience: "Expérience professionnelle",
            education: "Formation",
            skills: "Compétences",
            date_example: "janvier 2021 – mars 2023",
        },
        "it" => ResumeConventions {
            summary: "Profilo",
            experience: "Esperienza professionale",
            education: "Formazione",
            skills: "Competenze",
            date_example: "gennaio 2021 – marzo 2023",
        },
        "nl" => ResumeConventions {
            summary: "Profiel",
            experience: "Werkervaring",
            education: "Opleiding",
            skills: "Vaardigheden",
            date_example: "01/2021 – 03/2023",
        },
        "pt" => ResumeConventions {
            summary: "Perfil",
            experience: "Experiência profissional",
            education: "Formação",
            skills: "Competências",
            date_example: "janeiro 2021 – março 2023",
        },
        // "en" and every uncurated locale.
        _ => ResumeConventions {
            summary: "Professional Summary",
            experience: "Work Experience",
            education: "Education",
            skills: "Skills",
            date_example: "January 2021 – March 2023",
        },
    }
}
